import json, subprocess, sys, tempfile, shutil
b = '/tmp/claude-501/rdtdiff/target/release/caliper-docgen'
d = sys.argv[1]

for mode in (None, 'none'):
    extra = ['--collapse-inherited-props', mode] if mode else []
    out = subprocess.run([b, 'extract', '--src', d, '--json', '--html-attributes', 'full', '--include-unexported',
                          '--load-dependencies', '--quiet'] + extra, capture_output=True, text=True)
    j = json.loads(out.stdout)
    for k, c in j['components'].items():
        props = c['props']
        if isinstance(props, list):
            m = {}
            for i in props:
                m.update(j['propSets'][i])
            props = m
        print('collapse', mode or 'default (dependencies)', '|', c['displayName'], len(props), 'props listed;', sys.argv[2], 'in props:', sys.argv[2] in props)
        for l in c.get('inheritance', []):
            ms = l.get('members')
            if isinstance(ms, int):
                ms = j['nameLists'][ms]
            print('   layer', {x: (v if not isinstance(v, list) else len(v)) for x, v in l.items() if x != 'members'}, 'members', len(ms or []), sys.argv[2] in (ms or []))

