import json, subprocess, sys, tempfile, os, shutil
b = '/tmp/claude-501/rdtdiff/target/release/caliper-docgen'
f = os.path.abspath(sys.argv[1])
only = sys.argv[2:]
d = tempfile.mkdtemp(dir='/tmp/claude-501/rdtdiff/scratch-one')
shutil.copy(f, d)
out = subprocess.run([b, 'extract', '--src', d, '--json', '--html-attributes', 'full', '--include-unexported',
                      '--load-dependencies', '--collapse-inherited-props', 'none', '--quiet'], capture_output=True, text=True)
j = json.loads(out.stdout)


def strip(t):
    if isinstance(t, dict):
        return {k: strip(v) for k, v in t.items() if not (k == 'description' and v == '')}
    if isinstance(t, list):
        return [strip(v) for v in t]
    return t


for k, c in j['components'].items():
    print(c['displayName'], 'diagnostics:', c.get('diagnostics'))
    props = c['props']
    if isinstance(props, list):
        m = {}
        for i in props:
            m.update(j['propSets'][i])
        props = m
    for name, i in props.items():
        t = j['props'][i]
        if only:
            if name not in only:
                continue
        elif 'react' in json.dumps(t.get('declarations', '')).lower() or name in ('ref', 'key'):
            continue
        print('  ', name, json.dumps(strip(t['type']), separators=(',', ':')), '| degradedBy', t.get('degradedBy', []))
print('run diagnostics:', [x.get('message', x) for x in j.get('diagnostics', [])][:5])
shutil.rmtree(d)

